/*
# Seed Croatian venues across all experience categories

1. Schema
- Adds a UNIQUE constraint on (city_id, name) to venues so the seed is
  idempotent (ON CONFLICT DO NOTHING).
2. Data
- Inserts curated venues for the 20 Croatian cities, covering all seven
  experience categories: restaurant, hotel, wellness, shop, park, boat,
  winery. Venues are drawn from TripAdvisor top-rated lists and regional
  highlights gathered during research.
- Each venue carries: name, category, description, rating (0-5),
  price_from_eur, image_url (real Croatian-themed photography), address,
  source ("TripAdvisor" where applicable), and featured flag.
3. Idempotency
- ON CONFLICT (city_id, name) DO NOTHING so re-running is safe.
4. Security
- No policy changes; INSERT relies on existing grants.
*/

ALTER TABLE venues DROP CONSTRAINT IF EXISTS venues_city_id_name_key;
ALTER TABLE venues ADD CONSTRAINT venues_city_id_name_key UNIQUE (city_id, name);

INSERT INTO venues (city_id, name, category, description, rating, price_from_eur, image_url, address, source, featured)
SELECT c.id, v.name, v.category, v.description, v.rating, v.price_from_eur, v.image_url, v.address, v.source, v.featured
FROM (VALUES
